      (GodexRpsRenderer._androidGraphicSequence + 1) & 0xFFFFF;
  final micros = DateTime.now().microsecondsSinceEpoch.toRadixString(36);
  final sequence = GodexRpsRenderer._androidGraphicSequence
      .toRadixString(36)
      .padLeft(4, '0');
  return '$micros$sequence';
}

